import{Ht as e,Rt as t,dt as n,gt as r,mt as i,n as a}from"./chunks/framework.BkIgthgQ.js";var o=JSON.parse(`{"title":"Runtime architecture","description":"One process, two listeners. Disk static wins over embed. Admin proxies /api/v1/projects. Probe /api/v1/health.","frontmatter":{"title":"Runtime architecture","description":"One process, two listeners. Disk static wins over embed. Admin proxies /api/v1/projects. Probe /api/v1/health."},"headers":[],"relativePath":"en/contribute/architecture.md","filePath":"en/contribute/architecture.md","lastUpdated":1790057721000}`),s={name:`en/contribute/architecture.md`};function c(a,o,s,c,l,u){let d=e(`Mermaid`);return t(),n(`div`,null,[o[0]||=i(`<h1 id="runtime-architecture" tabindex="-1">Runtime architecture <a class="header-anchor" href="#runtime-architecture" aria-label="Permalink to “Runtime architecture”">​</a></h1><p><code>main.go</code> → <code>cmd.Run()</code>. Default <code>server</code>: one process, two listeners. Boot: three YAML files → logger → postgres → storage → cache → dual Gin → job workers.</p><ul><li>Client plane default <code>:8080</code> (updates / store / telemetry).</li><li>Admin plane default <code>:8081</code> (console + CI agent). <code>admin.enabled=false</code> skips the <strong>admin listener only</strong>.</li><li>Admin <strong>reverse-proxies</strong> <code>/api/v1/projects/**</code> to this process’s client plane (empty <code>ClientProxyURL</code> is tests only).</li></ul><p>Admin UI: <code>NoRoute</code>, never <code>gin.Static</code>. <code>frontend/embed.go</code> is <code>//go:embed all:dist</code>. Priority: non-empty <code>static_dir</code> with disk <code>index.html</code> → disk; else embedded FS with <code>index.html</code> → embed; <code>static_dir: &quot;&quot;</code> → UI off.</p><p>Probe <code>/api/v1/health</code>; <code>/api/v1/ready</code> is unregistered. <code>ready</code> excludes Redis. Cache: fail-closed at start, runtime fallback. Five log streams; both sinks off refuses listen. <code>ApplyTrustedProxies</code>: empty list <code>SetTrustedProxies(nil)</code>.</p>`,5),r(d,{code:`flowchart%20TB%0A%20%20subgraph%20proc%20%5Bkirivers%20process%5D%0A%20%20%20%20C%5BGin%20client%20%3A8080%5D%0A%20%20%20%20A%5BGin%20admin%20%3A8081%5D%0A%20%20%20%20S%5Bservice%5D%0A%20%20%20%20R%5Brepository%5D%0A%20%20%20%20DB%5B(PostgreSQL)%5D%0A%20%20%20%20ST%5Bstorage%5D%0A%20%20%20%20CA%5Bcache%20memory%2FRedis%5D%0A%20%20%20%20J%5Bjob%20workers%5D%0A%20%20%20%20A%20--%3E%7Cproxy%20%2Fapi%2Fv1%2Fprojects%7C%20C%0A%20%20%20%20C%20--%3E%20S%0A%20%20%20%20A%20--%3E%20S%0A%20%20%20%20S%20--%3E%20R%0A%20%20%20%20R%20--%3E%20DB%0A%20%20%20%20S%20--%3E%20ST%0A%20%20%20%20S%20--%3E%20CA%0A%20%20%20%20J%20--%3E%20S%0A%20%20end%0A%20%20UI%5BAdmin%20SPA%20disk%20or%20embed%5D%0A%20%20A%20--%3E%7CNoRoute%20static%7C%20UI%0A`})])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};